const P=window.PORTFOLIO,$=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const apps={welcome:['Welcome.exe','monitor'],projects:['My Projects','folder'],notes:['My Notes','note'],explorer:['My Computer','monitor'],media:['Media Player','media'],contact:['E-mail','mail'],github:['GitHub','github'],linkedin:['LinkedIn','linkedin'],documents:['My Documents','doc'],game:['Block Drop','game']};
let z=10,windows=new Map(),folder='Home',currentNote=0,track=0,playing=false,progress=0;
const icon=k=>`<span class="ico ${apps[k]?.[1]||k}" aria-hidden="true"></span>`;
Object.entries(apps).forEach(([key,[label]])=>{const b=document.createElement('button');b.className='desktop-icon';b.innerHTML=icon(key)+`<span>${label}</span>`;b.onclick=()=>openApp(key);$('#icons').append(b);});
function focusWin(id){windows.forEach((v,k)=>{v.el.classList.toggle('inactive',k!==id);v.task.classList.toggle('active',k===id&&!v.el.hidden)});const w=windows.get(id);w.el.style.zIndex=++z}
function closeWin(id){const w=windows.get(id);w?.cleanup?.();w?.el.remove();w?.task.remove();windows.delete(id)}
function makeWin(id,title,ico,body,width=650){if(windows.has(id)){windows.get(id).el.hidden=false;focusWin(id);return windows.get(id)}const el=document.createElement('section');el.className='window';el.setAttribute('aria-label',title);const count=windows.size;el.style.cssText=`width:${width}px;left:${Math.min(240+count*24,Math.max(6,innerWidth-width-30))}px;top:${Math.min(65+count*25,Math.max(8,innerHeight-480))}px`;el.innerHTML=`<header class="titlebar"><span class="ico ${ico}" aria-hidden="true"></span><strong>${esc(title)}</strong><div class="window-controls"><button data-control="min" aria-label="Minimize">_</button><button data-control="max" aria-label="Maximize">□</button><button data-control="close" aria-label="Close">×</button></div></header><div class="menubar"><span>File</span><span>Edit</span><span>View</span><span>Favorites</span><span>Tools</span><span>Help</span></div><div class="window-body">${body}</div><div class="status">Portfolio OS · Ready</div>`;$('#windows').append(el);const task=document.createElement('button');task.className='task';task.innerHTML=`<span class="ico ${ico}"></span><span>${esc(title)}</span>`;task.title=title;$('#tasks').append(task);const w={el,task};windows.set(id,w);task.onclick=()=>{if(!el.hidden&&task.classList.contains('active')){el.hidden=true;task.classList.remove('active')}else{el.hidden=false;focusWin(id)}};el.onpointerdown=()=>focusWin(id);el.querySelector('[data-control="close"]').onclick=()=>closeWin(id);el.querySelector('[data-control="min"]').onclick=()=>{el.hidden=true;task.classList.remove('active')};el.querySelector('[data-control="max"]').onclick=()=>el.classList.toggle('maximized');const bar=el.querySelector('.titlebar');bar.ondblclick=e=>{if(!e.target.closest('button'))el.classList.toggle('maximized')};bar.onpointerdown=e=>{if(e.target.closest('button')||el.classList.contains('maximized'))return;const x=e.clientX-el.offsetLeft,y=e.clientY-el.offsetTop;bar.setPointerCapture(e.pointerId);bar.onpointermove=ev=>{el.style.left=Math.max(0,Math.min(innerWidth-el.offsetWidth,ev.clientX-x))+'px';el.style.top=Math.max(0,Math.min(innerHeight-90,ev.clientY-y))+'px'};bar.onpointerup=()=>bar.onpointermove=null};focusWin(id);return w}
function message(title,text){makeWin('message-'+title,title,'doc',`<div class="paper">${esc(text)}</div>`,440)}
function external(key){const url=P[key];if(url&&/^https:\/\//.test(url))window.open(url,'_blank','noopener,noreferrer');else message(apps[key][0],`Your ${apps[key][0]} profile is not connected yet.\n\nAdd your profile URL to the ${key} field in content.js.`)}
function openApp(key){if(key==='github'||key==='linkedin')return external(key);if(windows.has(key)){windows.get(key).el.hidden=false;focusWin(key);return}if(key==='welcome')makeWin(key,'Welcome to Windows','monitor',`<div class="welcome classic-welcome"><div class="welcome-banner"><img src="icons/flag.svg" alt=""><div>Microsoft<small>Windows <b>98</b></small></div></div><div class="welcome-content"><div class="profile-intro"><a class="portrait-frame" href="${esc(P.photoFull || P.photo)}" target="_blank" rel="noopener noreferrer" aria-label="View portrait of ${esc(P.name)}"><img class="profile-portrait" width="96" height="120" fetchpriority="high" decoding="async" src="${esc(P.photo)}" alt="${esc(P.name)}"></a><div><span class="profile-kicker">Welcome to my desktop</span><h1>${esc(P.name)}</h1><p class="profile-role">${esc(P.role)}</p><p>Pretoria, South Africa</p></div></div><div class="welcome-options"><button onclick="openApp('projects')">${icon('projects')}<span><b>Explore my projects</b><small>Browse the things I’ve been building.</small></span></button><button onclick="openApp('explorer')">${icon('explorer')}<span><b>Browse my computer</b><small>Skills, documents, and certificates.</small></span></button><button onclick="openApp('contact')">${icon('contact')}<span><b>Connect to me</b><small>Send an e-mail and say hello.</small></span></button></div><p>${esc(P.about)}</p></div><div class="welcome-bottom"><label><input type="checkbox" checked id="show-welcome"> Show this screen at startup</label><button id="welcome-close">Close</button></div></div>`);else if(key==='projects'||key==='explorer'||key==='documents'){makeWin(key,apps[key][0],apps[key][1],'<div class="explorer-container"></div>',710);renderExplorer(key,key==='projects'?'Projects':key==='documents'?'Documents':'Home')}else if(key==='notes')openNotes();else if(key==='contact')openContact();else if(key==='media')openMedia();else if(key==='game')openGame()}
function renderExplorer(id,dir){const w=windows.get(id);w.folder=dir;const folders=['Home','Projects','Downloads','Documents'];let files='';if(dir==='Home')files=folders.slice(1).map(f=>`<button class="file" data-dir="${f}"><span class="ico folder"></span>${f}</button>`).join('');if(dir==='Projects')files=P.projects.map((p,i)=>`<a class="file project-link" href="${esc(p.url)}" target="_blank" rel="noopener noreferrer"><span class="ico web"></span><span>${esc(p.name)}</span><small>${esc(new URL(p.url).hostname)}</small><span class="open-live">Open live site </span></a>`).join('');if(dir==='Downloads')files=P.skills.map(s=>`<div class="document-file"><button class="file" data-skill="${esc(s)}"><span class="ico doc"></span>${esc(s)}.txt</button><a class="document-download" href="${esc(P.skillDetails[s].url)}" download>Download summary</a></div>`).join('');if(dir==='Downloads')files+=`<a class="file document-open" href="${esc(P.github)}" target="_blank" rel="noopener noreferrer"><span class="ico github"></span>My GitHub profile</a>`;if(dir==='Documents')files=P.documents.map((d,i)=>d.url?`<div class="document-file"><a class="file document-open" href="${esc(d.url)}" target="_blank" rel="noopener noreferrer"><span class="ico doc"></span><span>${esc(d.name)}</span></a>${d.download?`<a class="document-download" href="${esc(d.url)}" download>Download PDF</a>`:''}</div>`:`<button class="file" data-doc="${i}"><span class="ico doc"></span>${esc(d.name)}</button>`).join('');const previous=w.folderHistory||[];if(previous.at(-1)!==dir)previous.push(dir);w.folderHistory=previous;w.el.querySelector('.explorer-container').innerHTML=`<div class="toolbar classic-toolbar"><button data-back title="Back"><span class="arrow back"></span>Back</button><button data-forward title="Forward"><span class="arrow forward"></span>Forward</button><button data-dir="Home" title="Up one level"><span class="ico folder"></span>Up</button><i></i><button data-search><span class="ico search"></span>Search</button><button data-folders><span class="ico folder"></span>Folders</button><i></i><button data-view><span class="view-icon"></span>Views v</button></div><div class="address">Address <span><span class="ico ${dir==='Home'?'monitor':'folder'}"></span>${dir==='Home'?'My Computer':'C:\\Portfolio\\'+dir}<b>v</b></span><button data-dir="${dir}">Go</button></div><div class="explorer"><div class="sidebar folder-tree"><div class="tree-heading">Folders <button data-hide-tree aria-label="Hide folder tree">×</button></div><button data-dir="Home" class="tree-root">${icon('explorer')} Desktop</button><button data-dir="Home" class="tree-computer"><em>−</em>${icon('explorer')} My Computer</button><div class="tree-children"><button data-dir="Home"><em>−</em><span class="ico drive"></span>Portfolio (C:)</button><div class="tree-branches">${folders.slice(1).map(f=>`<button data-dir="${f}" class="${f===dir?'selected':''}"><em>+</em><span class="ico folder"></span>${f==='Documents'?'My Documents':f}</button>`).join('')}</div></div><button data-network class="tree-root"><span class="ico web"></span>Network Neighborhood</button></div><div class="files">${files}</div></div>`;w.el.querySelector('[data-back]').onclick=()=>{if(previous.length>1){(w.forwardHistory ||= []).push(previous.pop());const back=previous.pop();renderExplorer(id,back)}};w.el.querySelector('[data-forward]').onclick=()=>{const next=w.forwardHistory?.pop();if(next)renderExplorer(id,next)};w.el.querySelector('[data-folders]').onclick=()=>w.el.querySelector('.explorer').classList.toggle('no-tree');w.el.querySelector('[data-hide-tree]').onclick=()=>w.el.querySelector('.explorer').classList.add('no-tree');w.el.querySelector('[data-view]').onclick=()=>w.el.querySelector('.files').classList.toggle('list-view');w.el.querySelector('[data-search]').onclick=()=>{const box=document.createElement('input');box.placeholder='Search this folder';box.setAttribute('aria-label','Search this folder');box.className='folder-search';w.el.querySelector('.address').after(box);box.focus();box.oninput=()=>w.el.querySelectorAll('.file').forEach(f=>f.hidden=!f.textContent.toLowerCase().includes(box.value.toLowerCase()))};w.el.querySelector('[data-network]').onclick=()=>message('Network Neighborhood','You are exploring a portfolio on the World Wide Web.\n\nUse GitHub, LinkedIn or E-mail on the desktop to connect.');w.el.querySelectorAll('[data-dir]').forEach(b=>b.onclick=()=>renderExplorer(id,b.dataset.dir));w.el.querySelectorAll('[data-project]').forEach(b=>b.onclick=()=>project(+b.dataset.project));w.el.querySelectorAll('[data-doc]').forEach(b=>b.onclick=()=>{const d=P.documents[+b.dataset.doc];if(d.url&&/^https:\/\//.test(d.url))window.open(d.url,'_blank','noopener,noreferrer');else message(d.name,d.text)});w.el.querySelectorAll('[data-skill]').forEach(b=>b.onclick=()=>message(b.dataset.skill+'.txt',P.skillDetails[b.dataset.skill].text));w.el.querySelector('.status').textContent=(dir==='Home'?3:dir==='Projects'?P.projects.length:dir==='Downloads'?P.skills.length+1:P.documents.length)+' object(s) · C:\\Portfolio'}
function project(i){const p=P.projects[i];const w=makeWin('project'+i,p.name,'folder',`<div class="project-detail"><span class="eyebrow">PROJECT / ${p.tag}</span><h2>${esc(p.name)}</h2><p>${esc(p.description)}</p><ul>${(p.highlights||[]).map(h=>`<li>${esc(h)}</li>`).join('')}</ul><hr><p>${esc(p.stack)}</p><button class="preview-project">Play View demo & screenshots</button><button class="visit-project">Open project </button></div>`,510);w.el.querySelector('.preview-project').onclick=()=>{openApp('media');selectTrack(i)};w.el.querySelector('.visit-project').onclick=()=>p.url&&/^https:\/\//.test(p.url)?window.open(p.url,'_blank','noopener,noreferrer'):message(p.name,'Add this project’s live URL in content.js.')}
function openNotes(){const w=makeWin('notes','My Notes — Notepad','note',`<div class="note-layout"><div class="note-list">${P.notes.map((n,i)=>`<button data-note="${i}">${esc(n.title)}</button>`).join('')}</div><textarea class="note-edit" aria-label="Note contents" spellcheck="false"></textarea></div>`,650);const load=i=>{currentNote=i;let saved;try{saved=localStorage.getItem('portfolio-note-v2-'+P.notes[i].title)}catch{}w.el.querySelector('textarea').value=saved??P.notes[i].text;w.el.querySelectorAll('[data-note]').forEach(b=>b.classList.toggle('active',+b.dataset.note===i));w.el.querySelector('.status').textContent='Local notes · Changes save in this browser'};w.el.querySelectorAll('[data-note]').forEach(b=>b.onclick=()=>load(+b.dataset.note));w.el.querySelector('textarea').oninput=e=>{try{localStorage.setItem('portfolio-note-v2-'+P.notes[currentNote].title,e.target.value);w.el.querySelector('.status').textContent='Saved in this browser'}catch{w.el.querySelector('.status').textContent='Storage unavailable · Copy your note before closing'}};load(0)}
function openContact(){const w=makeWin('contact','New message — E-mail','mail',`<form class="contact"><span class="eyebrow">LET’S MAKE SOMETHING GOOD</span><h2>You’ve got an idea?</h2><p>I’d love to hear about it. Leave a little context below.</p><label>Your name<input name="name" placeholder="Ada Lovelace" required></label><label>Subject<input name="subject" placeholder="An interesting opportunity…" required></label><label>Message<textarea name="message" placeholder="Hello! I was exploring your desktop…" required></textarea></label><button type="submit"> Open in my e-mail app</button><p class="notice">${P.email?esc(P.email):'Contact setup pending — add your e-mail address in content.js.'}<br>This opens your mail application with a prepared draft.</p></form>`,510);w.el.querySelector('form').onsubmit=e=>{e.preventDefault();if(!P.email)return message('E-mail setup','Add your real e-mail address to content.js to enable contact drafts.');const f=new FormData(e.target);location.href='mailto:'+encodeURIComponent(P.email)+'?subject='+encodeURIComponent(f.get('subject'))+'&body='+encodeURIComponent(f.get('message')+'\n\nFrom: '+f.get('name'))}}
function openMedia(){const w=makeWin('media','Media Player — Project collection','media',`<div class="player"><div class="screen"></div><div class="transport"><button id="prev-track" aria-label="Previous project">Previous</button><button id="play" aria-label="Play preview">Play</button><button id="next-track" aria-label="Next project">Next</button><input type="range" id="seek" aria-label="Preview progress" value="0" max="100"><span id="elapsed">00:00</span></div><div class="playlist">${P.projects.map((p,i)=>`<button data-track="${i}"><span>0${i+1}. ${esc(p.name)}</span><span>concept preview</span></button>`).join('')}</div><p class="notice">Project collection · ${P.projects.length} tracks · Select a project to preview</p></div>`,560);w.el.querySelectorAll('[data-track]').forEach(b=>b.onclick=()=>selectTrack(+b.dataset.track));w.el.querySelector('#prev-track').onclick=()=>selectTrack((track+P.projects.length-1)%P.projects.length);w.el.querySelector('#next-track').onclick=()=>selectTrack((track+1)%P.projects.length);w.el.querySelector('#play').onclick=()=>{playing=!playing;const v=w.el.querySelector('video');if(v){if(playing)v.play().catch(()=>{});else v.pause()}w.el.querySelector('#play').textContent=playing?'Pause':'Play'};w.el.querySelector('#seek').oninput=e=>{progress=+e.target.value;const v=w.el.querySelector('video');if(v&&Number.isFinite(v.duration))v.currentTime=v.duration*progress/100};const timer=setInterval(()=>{if(!playing||w.el.hidden)return;progress=(progress+1)%101;w.el.querySelector('#seek').value=progress;w.el.querySelector('#elapsed').textContent='00:'+String(Math.floor(progress*.6)).padStart(2,'0');w.el.querySelectorAll('.demo-bars i').forEach(b=>b.style.setProperty('--h',20+Math.random()*80+'%'))},600);w.cleanup=()=>{clearInterval(timer);playing=false};selectTrack(track)}
function selectTrack(i){track=i;progress=0;const w=windows.get('media');if(!w)return;const p=P.projects[i];w.el.querySelectorAll('[data-track]').forEach(b=>b.classList.toggle('active',+b.dataset.track===i));const screen=w.el.querySelector('.screen');if(p.video){screen.innerHTML=`<video controls preload="metadata" src="${esc(p.video)}"></video>`}else if(p.images?.length){screen.innerHTML=`<img src="${esc(p.images[0])}" alt="${esc(p.name)} screenshot"><button style="position:absolute;bottom:8px;left:8px" id="next-image">Next screenshot Right</button>`;let n=0;screen.querySelector('button').onclick=()=>screen.querySelector('img').src=p.images[++n%p.images.length]}else screen.innerHTML=`<div class="demo" style="background:${p.color}"><div class="demo-top"><i></i><i></i><i></i><span style="margin-left:auto">${esc(p.name.toUpperCase())}</span></div><h2>${esc(p.name)}</h2><small>${esc(p.type)} / selected work</small><div class="demo-bars">${[42,68,48,86,63,95,77].map(h=>`<i style="--h:${h}%"></i>`).join('')}</div><small>DESIGNED TO MAKE THE EVERYDAY BETTER.</small></div><span class="sample-badge">ILLUSTRATIVE PREVIEW · PRESS PLAY</span>`;w.el.querySelector('#seek').value=0;playing=false;w.el.querySelector('#play').textContent='Play'}
function openGame(){const w=makeWin('game','Block Drop — A little break','game',`<div class="game-layout"><canvas width="200" height="400" aria-label="Falling block game board"></canvas><div class="game-info"><span class="eyebrow">DESKTOP ARCADE</span><h2>Block Drop</h2><p>Clear a line.<br>Clear your head.</p><small>SCORE</small><strong id="score">0000</strong><button id="newgame">New game</button><button id="pausegame">Pause</button><p>Left Right Move<br>Up Rotate · Down Drop<br>Space: hard drop<br>P: pause</p><div class="mobile-controls"><button data-move="left" aria-label="Move left">Left</button><button data-move="rotate" aria-label="Rotate">Rotate</button><button data-move="right" aria-label="Move right">Right</button><button data-move="drop" aria-label="Drop">Down</button></div></div></div>`,475);const ctx=w.el.querySelector('canvas').getContext('2d'),colors=['','#79d5cb','#c5a0ed','#eece75','#f29a9b','#8caee8'];let board,piece,score=0,paused=false,over=false;const shapes=[[[1,1,1,1]],[[2,0,0],[2,2,2]],[[3,3],[3,3]],[[0,4,4],[4,4,0]],[[0,5,0],[5,5,5]]];function spawn(){const s=shapes[Math.floor(Math.random()*shapes.length)];piece={x:3,y:0,s:s.map(r=>[...r])};if(hit())over=true}function hit(){return piece.s.some((r,y)=>r.some((v,x)=>v&&(piece.x+x<0||piece.x+x>=10||piece.y+y>=20||board[piece.y+y]?.[piece.x+x])))}function draw(){ctx.fillStyle='#131c29';ctx.fillRect(0,0,200,400);ctx.strokeStyle='#ffffff08';for(let x=0;x<10;x++)for(let y=0;y<20;y++)ctx.strokeRect(x*20,y*20,20,20);const block=(v,x,y)=>{if(!v)return;ctx.fillStyle=colors[v];ctx.fillRect(x*20+1,y*20+1,18,18);ctx.fillStyle='#ffffff55';ctx.fillRect(x*20+2,y*20+2,16,3)};board.forEach((r,y)=>r.forEach((v,x)=>block(v,x,y)));piece.s.forEach((r,y)=>r.forEach((v,x)=>block(v,piece.x+x,piece.y+y)));if(paused||over){ctx.fillStyle='#101724dd';ctx.fillRect(0,160,200,70);ctx.fillStyle='white';ctx.font='16px monospace';ctx.textAlign='center';ctx.fillText(over?'GAME OVER':'PAUSED',100,200)}}function down(){piece.y++;if(hit()){piece.y--;piece.s.forEach((r,y)=>r.forEach((v,x)=>{if(v)board[piece.y+y][piece.x+x]=v}));for(let y=19;y>=0;y--)if(board[y].every(Boolean)){board.splice(y,1);board.unshift(Array(10).fill(0));score+=100;y++}w.el.querySelector('#score').textContent=String(score).padStart(4,'0');spawn()}draw()}function move(action){if(paused||over||w.el.hidden)return;if(action==='drop'){while(!hit())piece.y++;piece.y--;down()}else if(action==='down')down();else if(action==='rotate'){const old=piece.s;piece.s=old[0].map((_,i)=>old.map(r=>r[i]).reverse());if(hit())piece.s=old}else{const d=action==='left'?-1:1;piece.x+=d;if(hit())piece.x-=d}draw()}function reset(){board=Array.from({length:20},()=>Array(10).fill(0));score=0;paused=false;over=false;w.el.querySelector('#score').textContent='0000';w.el.querySelector('#pausegame').textContent='Pause';spawn();draw()}const pause=()=>{paused=!paused;w.el.querySelector('#pausegame').textContent=paused?'Resume':'Pause';draw()};const key=e=>{if(w.el.hidden||w.el.classList.contains('inactive')||/INPUT|TEXTAREA/.test(e.target.tagName))return;const m={ArrowLeft:'left',ArrowRight:'right',ArrowUp:'rotate',ArrowDown:'down',' ':'drop'};if(m[e.key]){e.preventDefault();move(m[e.key])}if(e.key.toLowerCase()==='p')pause()};document.addEventListener('keydown',key);w.el.querySelector('#newgame').onclick=reset;w.el.querySelector('#pausegame').onclick=pause;w.el.querySelectorAll('[data-move]').forEach(b=>b.onclick=()=>move(b.dataset.move));const timer=setInterval(()=>{if(!paused&&!over&&!w.el.hidden&&!w.el.classList.contains('inactive'))down()},650);w.cleanup=()=>{clearInterval(timer);document.removeEventListener('keydown',key)};reset()}
$('#start').onclick=()=>$('#startmenu').hidden=!$('#startmenu').hidden;document.addEventListener('pointerdown',e=>{if(!e.target.closest('#startmenu')&&!e.target.closest('#start'))$('#startmenu').hidden=true});$('#showdesktop').onclick=()=>windows.forEach(w=>{w.el.hidden=true;w.task.classList.remove('active')});const clock=()=>$('#clock').textContent=new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'});clock();setInterval(clock,1000);try{if(localStorage.getItem('portfolio-welcome')!=='off')openApp('welcome')}catch{openApp('welcome')}


// Windows 98 Start menu: hover or click to open a cascading submenu.
const startItems=[['Programs','folder',[['My Projects','projects'],['Notepad','notes'],['Windows Media Player','media'],['Block Drop','game']]],['Documents','doc',[['My Documents','documents'],['My Notes','notes']]],['Settings','settings',[['Desktop properties','properties']]],['Find','search',[['Files or Folders…','explorer']]],['Help','doc','help'],['Run…','monitor','run'],['Log Off…','power','logoff'],['Shut Down…','power','shutdown']];
$('#startmenu aside').innerHTML='Windows <b>98</b>';
$('#startitems').innerHTML=startItems.map(([label,ico,action],i)=>`<div class="start-entry ${i===6?'start-separator':''}"><button class="start-item" data-start="${i}"><span class="ico ${ico}"></span><span>${label}</span>${Array.isArray(action)?'<b class="submenu-arrow" aria-hidden="true"></b>':''}</button>${Array.isArray(action)?`<div class="start-submenu" hidden>${action.map(([text,key])=>`<button data-launch="${key}"><span class="ico ${apps[key]?.[1]||'settings'}"></span>${text}</button>`).join('')}</div>`:''}</div>`).join('');
function startAction(key){$('#startmenu').hidden=true;if(apps[key])return openApp(key);if(key==='properties')return message('Display Properties','Classic Windows theme\n\nBackground: Teal\nAppearance: Windows Standard\n\nThis desktop is your interactive portfolio.');if(key==='help')return message('Windows Help','Click a desktop icon to open an application.\nDrag a title bar to move a window.\nUse the taskbar to switch applications.\n\nMy Computer contains projects, downloaded skills, and personal documents.');if(key==='run'){const w=makeWin('run','Run','monitor','<form class="run-dialog"><p>Type the name of a program and Windows will open it for you.</p><label>Open: <input name="command" placeholder="notepad" required></label><div><button>OK</button><button type="button" data-cancel>Cancel</button></div></form>',390);w.el.querySelector('form').onsubmit=e=>{e.preventDefault();const value=new FormData(e.target).get('command').toLowerCase();const key=({notepad:'notes',explorer:'explorer',wmplayer:'media',tetris:'game',projects:'projects'})[value];if(key){closeWin('run');openApp(key)}else message('Run','Cannot find '+value+'. Try notepad, explorer, wmplayer, projects, or tetris.')};w.el.querySelector('[data-cancel]').onclick=()=>closeWin('run');return}const w=makeWin('shutdown',key==='logoff'?'Log Off Windows':'Shut Down Windows','power','<div class="shutdown-dialog"><img src="icons/flag.svg" alt=""><div><p>What do you want the computer to do?</p><label><input type="radio" checked> Return to the desktop</label><p>Your portfolio session will stay available.</p><button id="shutdown-ok">OK</button></div></div>',410);w.el.querySelector('#shutdown-ok').onclick=()=>{closeWin('shutdown');$('#showdesktop').click()}}
$('#startitems').querySelectorAll('[data-start]').forEach(b=>{const i=+b.dataset.start;const entry=b.parentElement;const submenu=entry.querySelector('.start-submenu');const reveal=()=>{$('#startitems').querySelectorAll('.start-submenu').forEach(s=>s.hidden=s!==submenu);$('#startitems').querySelectorAll('.start-item').forEach(s=>s.classList.toggle('menu-active',s===b));if(submenu)submenu.hidden=false};entry.onmouseenter=reveal;b.onclick=()=>Array.isArray(startItems[i][2])?reveal():startAction(startItems[i][2]);});
$('#startitems').querySelectorAll('[data-launch]').forEach(b=>b.onclick=()=>startAction(b.dataset.launch));document.addEventListener('keydown',e=>{if(e.key==='Escape')$('#startmenu').hidden=true});
document.addEventListener('change',e=>{if(e.target.id==='show-welcome')try{localStorage.setItem('portfolio-welcome',e.target.checked?'on':'off')}catch{}});document.addEventListener('click',e=>{if(e.target.id==='welcome-close')closeWin('welcome')});






